css:
.ts { display: flex; align-items: flex-start; gap: 12px; width: 320px; padding: 14px 16px; box-sizing: border-box; background: #ecfdf5; border: 1px solid #a7f3d0; border-radius: 10px; color: #065f46; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ts-icon { flex: none; width: 24px; height: 24px; border-radius: 50%; background: #10b981; color: #fff; font-size: 14px; font-weight: 700; line-height: 24px; text-align: center; }
.ts-title { margin: 0; font-size: 14px; font-weight: 700; }
.ts-sub { margin: 2px 0 0; font-size: 12px; opacity: 0.85; line-height: 1.6; }

.te { display: flex; align-items: flex-start; gap: 12px; width: 320px; padding: 14px 16px; box-sizing: border-box; background: #fef2f2; border: 1px solid #fecaca; border-radius: 10px; color: #991b1b; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.te-icon { flex: none; width: 24px; height: 24px; border-radius: 50%; background: #ef4444; color: #fff; font-size: 14px; font-weight: 700; line-height: 24px; text-align: center; }
.te-title { margin: 0; font-size: 14px; font-weight: 700; }
.te-sub { margin: 2px 0 0; font-size: 12px; opacity: 0.85; line-height: 1.6; }

.tw { display: flex; align-items: flex-start; gap: 12px; width: 320px; padding: 14px 16px; box-sizing: border-box; background: #fffbeb; border: 1px solid #fde68a; border-radius: 10px; color: #92400e; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.tw-icon { flex: none; width: 24px; height: 24px; border-radius: 50%; background: #f59e0b; color: #fff; font-size: 14px; font-weight: 700; line-height: 24px; text-align: center; }
.tw-title { margin: 0; font-size: 14px; font-weight: 700; }
.tw-sub { margin: 2px 0 0; font-size: 12px; opacity: 0.85; line-height: 1.6; }

.ti { display: flex; align-items: flex-start; gap: 12px; width: 320px; padding: 14px 16px; box-sizing: border-box; background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 10px; color: #1e40af; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ti-icon { flex: none; width: 24px; height: 24px; border-radius: 50%; background: #3b82f6; color: #fff; font-size: 14px; font-weight: 700; line-height: 24px; text-align: center; }
.ti-title { margin: 0; font-size: 14px; font-weight: 700; }
.ti-sub { margin: 2px 0 0; font-size: 12px; opacity: 0.85; line-height: 1.6; }

.ic { display: flex; align-items: center; gap: 12px; width: 330px; padding: 12px 14px; box-sizing: border-box; background: #fff; border-radius: 12px; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.14); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ic-icon { flex: none; width: 40px; height: 40px; border-radius: 10px; background: #fef3c7; font-size: 20px; line-height: 40px; text-align: center; }
.ic-body { flex: 1; min-width: 0; }
.ic-title { margin: 0; font-size: 13px; font-weight: 700; }
.ic-text { margin: 2px 0 0; font-size: 12px; line-height: 1.5; color: #6b7280; }
.ic-time { flex: none; align-self: flex-start; font-size: 11px; color: #9ca3af; }

.dm { display: flex; align-items: center; justify-content: space-between; gap: 16px; width: 320px; padding: 12px 12px 12px 16px; box-sizing: border-box; background: #fff; border: 1px solid #e5e7eb; border-radius: 10px; box-shadow: 0 6px 18px rgba(0, 0, 0, 0.1); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.dm-text { margin: 0; font-size: 14px; }
.dm-close { width: 28px; height: 28px; border: 0; border-radius: 6px; background: transparent; color: #6b7280; font-size: 20px; line-height: 1; cursor: pointer; }
.dm-close:hover { background: #f3f4f6; color: #111827; }

.pg { position: relative; width: 320px; padding: 14px 16px 18px; box-sizing: border-box; overflow: hidden; background: #fff; border-radius: 10px; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.14); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.pg-text { margin: 0; font-size: 14px; }
.pg-bar { position: absolute; left: 0; bottom: 0; height: 4px; width: 100%; background: #6366f1; transform-origin: left; animation: pg-shrink 4s linear infinite; }
@keyframes pg-shrink { from { transform: scaleX(1); } to { transform: scaleX(0); } }

.ac { display: flex; align-items: center; justify-content: space-between; gap: 20px; width: 320px; padding: 12px 14px 12px 18px; box-sizing: border-box; background: #1f2937; border-radius: 10px; color: #fff; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ac-text { margin: 0; font-size: 14px; }
.ac-undo { padding: 6px 10px; border: 0; border-radius: 6px; background: transparent; color: #93c5fd; font-size: 13px; font-weight: 700; cursor: pointer; }
.ac-undo:hover { background: rgba(255, 255, 255, 0.1); }

.dk { display: flex; align-items: center; gap: 12px; width: 320px; padding: 14px 16px; box-sizing: border-box; background: #111827; border: 1px solid #374151; border-radius: 12px; box-shadow: 0 10px 28px rgba(0, 0, 0, 0.3); color: #f9fafb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.dk-icon { flex: none; width: 28px; height: 28px; border-radius: 8px; background: #22c55e; color: #052e16; font-size: 15px; font-weight: 800; line-height: 28px; text-align: center; }
.dk-title { margin: 0; font-size: 14px; font-weight: 700; }
.dk-text { margin: 2px 0 0; font-size: 12px; color: #9ca3af; }

.ab { width: 330px; padding: 14px 16px; box-sizing: border-box; background: #fff; border-left: 4px solid #6366f1; border-radius: 6px; box-shadow: 0 6px 20px rgba(0, 0, 0, 0.12); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ab-title { margin: 0 0 4px; font-size: 14px; font-weight: 700; color: #4338ca; }
.ab-text { margin: 0; font-size: 13px; line-height: 1.7; color: #4b5563; }
